interface.definition:
a!localVariables(
  {
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      label: "DETAILS",
      contents: {
        #"SYSTEM_SYSRULES_columnsLayout"(
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_textField"(
                  label: "ORGANIZATION NAME",
                  labelPosition: "ABOVE",
                  placeholder: "Enter The Organization Name",
                  value: ri!organizationdetails[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/0f073a93-5255-4fd3-bdba-87d2febf50e9"],
                  saveInto: {
                    ri!organizationdetails[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/0f073a93-5255-4fd3-bdba-87d2febf50e9"]

                  },
                  refreshAfter: "KEYPRESS",
                  required: true(),
                  requiredMessage: "Please enter the Organization Name",
                  validations: {
                    if(
                      len(
                        ri!organizationdetails[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/0f073a93-5255-4fd3-bdba-87d2febf50e9"]
                      ) < 3,
                      "Must be at least 3 characters",
                      ""
                    )

                  }
                ),

              }
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
               #"SYSTEM_SYSRULES_pickerFieldUsers"(
                 label: "Project Manager",
                 required: true(),
                 maxSelections: 1,
                groupFilter: #"_a-0000eef8-4604-8000-9e54-011c48011c48_1128889",
                 value: ri!organizationdetails[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/4b67e544-964e-485d-90df-3947cc4b80b2"],
                 saveInto: ri!organizationdetails[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/4b67e544-964e-485d-90df-3947cc4b80b2"]
               )

              }
            )

          }
        ),
        #"SYSTEM_SYSRULES_columnsLayout"(
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_radioButtonField_v1"(
                label: "Parent Organization",
                labelPosition: "ABOVE",
                value: ri!organizationdetails[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/56279cd7-e7c5-4577-9c40-eae4b315ac12"],
                saveInto: {
                  ri!organizationdetails[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/56279cd7-e7c5-4577-9c40-eae4b315ac12"]
                },
                choiceLabels: {"Yes", "No"},
                choiceValues: {true(), false()},
                validations: {},
                choiceLayout: "STACKED"
                )

              }
            )

          }
        )

      }
    )
  }
)
